@import url('https://fonts.googleapis.com/css2?family=Cormorant+Garamond:wght@400;500;600&family=Montserrat:wght@300;500&display=swap');
*{box-sizing:border-box}html,body{margin:0;width:100%;height:100%;overflow:hidden;background:#100b08}
body{font-family:Montserrat,sans-serif}.stage{position:relative;width:100vw;height:100vh;overflow:hidden}
.bg{position:absolute;inset:0;background:url("data:image/png;base64,") center/cover no-repeat;filter:saturate(.9)}
/* use the upper-left storyboard panel as the opening scene */
.opening{position:absolute;inset:0;background-image:linear-gradient(rgba(20,10,6,.04),rgba(20,10,6,.28)),url("data:image/png;base64,");background-size:200% 400%;background-position:0 0;transition:opacity .8s,transform 1s}
.opening.hide{opacity:0;transform:scale(1.06)}
.frame{position:absolute;inset:18px;border:1px solid #e5c37e99;z-index:8;pointer-events:none}
.copy{position:absolute;z-index:9;left:50%;top:52%;transform:translate(-50%,-50%);text-align:center;width:88%;text-shadow:0 2px 18px #0009;color:#fff5df;transition:opacity .5s}
.copy.hide{opacity:0}
.kicker{font-size:9px;letter-spacing:.34em;text-transform:uppercase}
.names{font:500 clamp(58px,10vw,120px) "Cormorant Garamond",serif;color:#f1d18e;margin:15px 0}
.script{font:italic clamp(24px,3.4vw,42px) "Cormorant Garamond",serif}
.hint{margin-top:26px;font-size:8px;letter-spacing:.28em;text-transform:uppercase;color:#fff0c7cc}
.envelope{position:absolute;z-index:20;left:50%;top:50%;width:min(520px,78vw);height:min(340px,50vw);transform:translate(-50%,-50%) scale(.35);opacity:0;transition:all 1s cubic-bezier(.2,.8,.2,1);perspective:1000px}
.envelope.show{opacity:1;transform:translate(-50%,-50%) scale(1)}
.envbody{position:absolute;inset:0;background:#eee2cd;box-shadow:0 22px 70px #0008;border-radius:4px;overflow:hidden}
.envbody:before{content:"";position:absolute;inset:0;background:linear-gradient(135deg,#f9f1e3,#d9c4a0 49%,#f7ecdc 50%)}
.seal{position:absolute;z-index:4;left:50%;top:50%;transform:translate(-50%,-50%);width:70px;height:70px;border-radius:50%;background:#b28b4b;color:#fff1c7;display:grid;place-items:center;font:24px "Cormorant Garamond";box-shadow:0 5px 16px #5c3f1c55}
.flap{position:absolute;z-index:3;left:0;top:0;width:100%;height:58%;background:#f6ead8;clip-path:polygon(0 0,100% 0,50% 100%);transform-origin:top;transition:transform 1.1s cubic-bezier(.2,.75,.2,1)}
.envelope.open .flap{transform:rotateX(180deg)}
.letter{position:absolute;z-index:2;left:8%;right:8%;top:7%;height:86%;background:#fffaf0;box-shadow:0 8px 24px #0002;padding:42px 25px;text-align:center;color:#4a4035;transform:translateY(12%);transition:transform 1.1s .15s cubic-bezier(.2,.75,.2,1)}
.envelope.open .letter{transform:translateY(-18%)}
.letter .mini{font:8px Montserrat;letter-spacing:.3em;text-transform:uppercase}
.letter h1{font:500 clamp(36px,6vw,68px) "Cormorant Garamond";margin:14px 0;color:#8f6e3c}
.letter p{font:italic 22px "Cormorant Garamond";margin:8px 0}
.next{position:absolute;z-index:25;left:50%;bottom:30px;transform:translateX(-50%);border:1px solid #d9b56e;background:#170e09cc;color:#f6dfad;padding:12px 22px;font:8px Montserrat;letter-spacing:.25em;text-transform:uppercase;opacity:0;pointer-events:none;transition:opacity .6s}
.next.show{opacity:1;pointer-events:auto}
.bokeh{position:absolute;z-index:30;left:var(--x);top:var(--y);width:var(--s);height:var(--s);border-radius:50%;background:#f1cf8d;box-shadow:0 0 25px #e5bd6b;filter:blur(var(--blur));opacity:0;pointer-events:none}
.bokeh.go{animation:burst var(--d) ease-out forwards}
@keyframes burst{0%{opacity:0;transform:scale(.15) translate(0,0)}12%{opacity:.9}100%{opacity:0;transform:scale(1.4) translate(var(--dx),var(--dy))}}
.pet{position:absolute;z-index:31;left:var(--x);top:48%;width:12px;height:20px;border-radius:70% 20%;background:#f6ddd7;opacity:0;pointer-events:none}
.pet.go{animation:petal var(--d) ease-in forwards}
@keyframes petal{0%{opacity:0;transform:translate(0,0) rotate(0)}12%{opacity:.9}100%{opacity:0;transform:translate(var(--dx),var(--dy)) rotate(500deg)}}